// Package shopify holds Shopify per-event webhook mappers.
package shopify

import (
	"context"

	wire "template/contracts-go/wire"
	"template/api-go/internal/sync/enums"
	syncevents "template/api-go/internal/sync/events"
	"template/api-go/internal/sync/services/pipelines"
	syncshopify "template/api-go/internal/sync/services/shopify"
	"template/api-go/internal/webhooks/mappers"
	"template/core-go/types"
)

// OrderUpdatedMapper maps a verified Shopify "orders/updated" webhook
// body into a sync.ExternalOrderUpdatedEvent by reusing the sync
// Shopify orders normalizer. The MapContext carries the store identifiers
// extracted from the webhook URL (?storeId) so the Order aggregate
// receives a non-empty StoreID.
type OrderUpdatedMapper struct {
	normalizer *syncshopify.OrdersNormalizer
}

// NewOrderUpdatedMapper constructs the mapper. Pass
// syncshopify.NewOrdersNormalizer() for the normalizer.
func NewOrderUpdatedMapper(n *syncshopify.OrdersNormalizer) *OrderUpdatedMapper {
	return &OrderUpdatedMapper{normalizer: n}
}

func (m *OrderUpdatedMapper) Platform() enums.WebhookPlatform { return enums.WebhookPlatformShopify }
func (m *OrderUpdatedMapper) Event() wire.SyncEventName       { return wire.SyncEventNameEXTERNAL_ORDER_UPDATED }

// Map normalizes rawBody through the sync Shopify orders normalizer,
// populating RunInput from mc so the downstream Order aggregate has a
// non-empty StoreID, then wraps the result in a sync.ExternalOrderUpdatedEvent.
func (m *OrderUpdatedMapper) Map(_ context.Context, rawBody []byte, mc mappers.MapContext) ([]types.DomainEventI, error) {
	input, err := m.normalizer.Normalize(rawBody, pipelines.RunInput{
		StoreID:                    mc.StoreID,
		StoreIntegrationID:         mc.StoreIntegrationID,
		StoreIntegrationExternalID: mc.StoreIntegrationExternalID,
	})
	if err != nil {
		return nil, err
	}
	evt := syncevents.NewExternalOrderUpdated(input, mc.StoreID)
	return []types.DomainEventI{evt}, nil
}

