// Package webhooks provides the fx.Module for the Go-worker webhooks
// bounded context. Receives inbound provider webhooks via a single
// POST /webhooks?platform&event&integrationId&storeId endpoint that
// verifies the per-platform signature and publishes a WebhookReceivedEvent.
// A registered handler maps it through a (platform,event) mapper factory
// into sync.ExternalXUpdatedEvent(s) — Spec A's per-entity handlers then
// persist canonical aggregates and publish wire integration events.
//
// Real mapper coverage:
//   - SHOPIFY   / sync.external_order_updated  → ExternalOrderUpdatedEvent  (via Shopify normalizer)
//   - NUVEM_SHOP / sync.external_order_updated  → ExternalOrderUpdatedEvent  (fetches full order via API)
//   - NUVEM_SHOP / sync.external_product_updated → ExternalProductUpdatedEvent (fetches full product via API)
//
// All other (platform,event) pairs register as PendingMappers that return
// WEBHOOK_MAPPER_PENDING so the handler surfaces a graceful error rather
// than a 500. Add real mappers under internal/webhooks/mappers/ as they land.
package webhooks

import (
	"context"
	"os"
	"strings"

	wire "template/contracts-go/wire"
	"template/api-go/internal/sync/enums"
	syncnuvemshop "template/api-go/internal/sync/services/nuvemshop"
	syncshopify "template/api-go/internal/sync/services/shopify"
	"template/api-go/internal/webhooks/controllers"
	_ "template/api-go/internal/webhooks/errors" // init() registers HTTP status codes
	"template/api-go/internal/webhooks/handlers"
	"template/api-go/internal/webhooks/mappers"
	mapnuvemshop "template/api-go/internal/webhooks/mappers/nuvemshop"
	mapshopify "template/api-go/internal/webhooks/mappers/shopify"
	"template/api-go/internal/webhooks/services"
	"template/core-go/services/mediator"
	"template/core-go/types"

	"go.uber.org/fx"
)

func provideController[T types.Controller](ctor any) fx.Option {
	return fx.Provide(fx.Annotate(ctor,
		fx.As(new(types.Controller)),
		fx.ResultTags(`group:"controllers"`),
	))
}

func provideVerifier[T services.WebhookVerifier](ctor any) fx.Option {
	return fx.Provide(fx.Annotate(ctor,
		fx.As(new(services.WebhookVerifier)),
		fx.ResultTags(`group:"webhook_verifiers"`),
	))
}

func provideMapper[T mappers.WebhookMapper](ctor any) fx.Option {
	return fx.Provide(fx.Annotate(ctor,
		fx.As(new(mappers.WebhookMapper)),
		fx.ResultTags(`group:"webhook_mappers"`),
	))
}

// --- Per-platform verifier factory helpers ---

// shopifyVerifierFromEnv reads the Shopify app secret from env.
// Returns an instance configured with the empty string when unset —
// the verifier then rejects every signature (fail-closed).
func shopifyVerifierFromEnv() *services.ShopifyVerifier {
	return services.NewShopifyVerifier(os.Getenv("SHOPIFY_WEBHOOK_SECRET"))
}

// Per-platform plain-HMAC verifiers — all use canonical underscore spelling.
func nuvemShopVerifierFromEnv() *services.HMACVerifier {
	return services.NewHMACVerifier(enums.WebhookPlatformNuvemShop, "X-Linkedstore-Hmac-Sha256", services.HMACSHA256, services.HexLower, os.Getenv("NUVEMSHOP_WEBHOOK_SECRET"))
}
func yampiVerifierFromEnv() *services.HMACVerifier {
	return services.NewHMACVerifier(enums.WebhookPlatformYampi, "X-Yampi-Hmac-Sha256", services.HMACSHA256, services.HexLower, os.Getenv("YAMPI_WEBHOOK_SECRET"))
}
// KIWIFY_WEBHOOK_SECRET accepts a comma-separated list of signing keys.
// A request validates if any one of them matches (supports rotation and
// multiple Kiwify products/stores sharing this worker).
func kiwifyVerifierFromEnv() *services.HMACVerifier {
	secrets := splitCSVSecrets(os.Getenv("KIWIFY_WEBHOOK_SECRET"))
	return services.NewHMACVerifier(enums.WebhookPlatformKiwify, "X-Kiwify-Signature", services.HMACSHA1, services.HexLower, secrets...)
}

func splitCSVSecrets(raw string) []string {
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := strings.TrimSpace(p); s != "" {
			out = append(out, s)
		}
	}
	return out
}
func cartPandaVerifierFromEnv() *services.HMACVerifier {
	return services.NewHMACVerifier(enums.WebhookPlatformCartPanda, "X-Cartpanda-Signature", services.HMACSHA512, services.HexLower, os.Getenv("CARTPANDA_WEBHOOK_SECRET"))
}
func stripeVerifierFromEnv() *services.StripeVerifier {
	return services.NewStripeVerifier(os.Getenv("STRIPE_WEBHOOK_SECRET"))
}
func metaVerifierFromEnv() *services.MetaVerifier {
	return services.NewMetaVerifier(os.Getenv("META_WEBHOOK_SECRET"))
}
func tikTokVerifierFromEnv() *services.TikTokVerifier {
	return services.NewTikTokVerifier(os.Getenv("TIKTOK_WEBHOOK_SECRET"))
}
func googleAdsVerifierFromEnv() *services.GoogleAdsVerifier {
	return services.NewGoogleAdsVerifier(os.Getenv("GOOGLE_ADS_VERIFICATION_TOKEN"))
}

// mediatorPublisher satisfies handlers.ExternalEventPublisher by dispatching
// inline through the InternalMediator — the same shape as executor.syncPublisher
// in the sync package. Inline dispatch ensures the sync ExternalXUpdatedHandler
// persists entities before the webhook handler returns.
type mediatorPublisher struct{ m mediator.InternalMediator }

func (p mediatorPublisher) Publish(ctx context.Context, e types.DomainEventI) error {
	return p.m.Dispatch(ctx, e)
}

var Module = fx.Module("webhooks",
	// --- Per-platform verifiers into group:"webhook_verifiers" ---
	provideVerifier[*services.ShopifyVerifier](shopifyVerifierFromEnv),
	provideVerifier[*services.HMACVerifier](nuvemShopVerifierFromEnv),
	provideVerifier[*services.HMACVerifier](yampiVerifierFromEnv),
	provideVerifier[*services.HMACVerifier](kiwifyVerifierFromEnv),
	provideVerifier[*services.HMACVerifier](cartPandaVerifierFromEnv),
	provideVerifier[*services.StripeVerifier](stripeVerifierFromEnv),
	provideVerifier[*services.MetaVerifier](metaVerifierFromEnv),
	provideVerifier[*services.TikTokVerifier](tikTokVerifierFromEnv),
	provideVerifier[*services.GoogleAdsVerifier](googleAdsVerifierFromEnv),

	// WebhookVerifierFactory aggregates the platform group.
	fx.Provide(fx.Annotate(
		services.NewWebhookVerifierFactory,
		fx.ParamTags(`group:"webhook_verifiers"`),
	)),

	// --- Normalizers (shared with sync pipelines) ---
	// *syncshopify.OrdersNormalizer (plural) is webhook-specific — sync provides
	// the singular *OrderNormalizer, so there's no conflict here.
	fx.Provide(func() *syncshopify.OrdersNormalizer {
		return syncshopify.NewOrdersNormalizer()
	}),
	// *syncnuvemshop.OrderNormalizer / *ProductNormalizer are provided by sync.Module
	// (composed in the same fx.New) — consume them, don't re-declare, or fx errors
	// with "already provided". Same convention as credentials.Exchanger below.
	// Nuvemshop HTTP client (single-resource GETs for webhook mappers).
	// *syncnuvemshop.Client satisfies mapnuvemshop.NuvemshopHTTPClient via GetOrderByID / GetProductByID.
	fx.Provide(func() mapnuvemshop.NuvemshopHTTPClient {
		return syncnuvemshop.NewClient(syncnuvemshop.ClientConfig{})
	}),
	// credentials.Exchanger is provided by sync.Module (which is composed in the
	// same fx.New call) — no re-declaration needed; fx will inject it here.

	// --- Mappers into group:"webhook_mappers" ---
	// Real: SHOPIFY / sync.external_order_updated + sync.external_product_updated + sync.external_pixel_event_recorded
	provideMapper[*mapshopify.OrderUpdatedMapper](mapshopify.NewOrderUpdatedMapper),
	provideMapper[*mapshopify.ProductUpdatedMapper](mapshopify.NewProductUpdatedMapper),
	provideMapper[*mapshopify.PixelEventRecordedMapper](mapshopify.NewPixelEventRecordedMapper),
	// Real: NUVEM_SHOP / sync.external_order_updated + sync.external_product_updated
	provideMapper[*mapnuvemshop.OrderUpdatedMapper](mapnuvemshop.NewOrderUpdatedMapper),
	provideMapper[*mapnuvemshop.ProductUpdatedMapper](mapnuvemshop.NewProductUpdatedMapper),

	// Pending stubs for all other known (platform,event) pairs.
	fx.Options(pendingMapperProviders()...),

	// mappers.Factory aggregates the (platform,event) group.
	fx.Provide(fx.Annotate(
